// PODATNE: serwer pobiera DOWOLNY URL podany przez uzytkownika
String fetchImageVulnerable(String userProvidedUrl) throws IOException {
    return new String(new URL(userProvidedUrl).openStream().readAllBytes());
    // userProvidedUrl = "http://169.254.169.254/latest/meta-data/" -> wyciek danych chmury!
}

// OBRONA (koncepcyjnie): allowlist dozwolonych hostow, blokada adresow prywatnych/loopback
boolean isAllowedHost(String url) throws Exception {
    String host = new URL(url).getHost();
    return Set.of("images.trusted-cdn.com").contains(host); // TYLKO jawnie dozwolone hosty
}

